import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Plugin API: evolution and migration","description":"Compatibility decisions, migration and SemVer policy","frontmatter":{"navigation":{"category":"Plugin API"},"title":"Plugin API: evolution and migration","description":"Compatibility decisions, migration and SemVer policy","editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/plugin-api/api-evolution-and-migration.md"},"headers":[],"relativePath":"docs/plugin-api/api-evolution-and-migration.md","filePath":"docs/plugin-api/api-evolution-and-migration.md","lastUpdated":1792252051000}`),a={name:`docs/plugin-api/api-evolution-and-migration.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="api-evolution-and-migration" tabindex="-1">API evolution and migration <a class="header-anchor" href="#api-evolution-and-migration" aria-label="Permalink to “API evolution and migration”">​</a></h1><p>If your plugin uses <code>@pumpkinmc/pumpkin-api-ts</code>, use the <a href="./../../tools/pumpkin-api/docs/migration">migration guide</a> for the package and build changes. This page explains what the compatibility audit covers and how the API&#39;s version numbers signal changes.</p><h2 id="what-the-compatibility-audit-covers" tabindex="-1">What the compatibility audit covers <a class="header-anchor" href="#what-the-compatibility-audit-covers" aria-label="Permalink to “What the compatibility audit covers”">​</a></h2><p>The <code>v0.1.1</code> API from <code>@pumpkinmc/pumpkin-api-ts</code> is the compatibility baseline. The <a href="../../tools/pumpkin-api/compatibility/v0.1.1.json">compatibility inventory</a> records a decision for every runtime export, public TypeScript type, WIT declaration and operation. Check it when you need to know whether a specific part of the old API is preserved.</p><p>The new facade also changes a few runtime behaviors:</p><ul><li>Missing command-suggestion handlers now report the requested handler ID.</li><li>IPC rejection paths now throw descriptive <code>Error</code> objects.</li><li>The facade releases event, command, suggestion, AI-goal and chunk-generator callbacks after <code>onUnload()</code>, even if the hook throws. It also removes event and command callbacks when host registration fails.</li><li>Scheduled task helpers reject runtime tick values that aren&#39;t numbers or bigints.</li></ul><p>The <a href="./../../tools/pumpkin-api/docs/migration">migration guide</a> explains what these changes mean for your plugin, including which old error assertions to update and when callbacks need to be registered again.</p><h2 id="package-and-build-changes" tabindex="-1">Package and build changes <a class="header-anchor" href="#package-and-build-changes" aria-label="Permalink to “Package and build changes”">​</a></h2><p>Move to <code>@pumpkin-plugins/pumpkin-api</code> for the runtime API and <code>@pumpkin-plugins/build</code> for the <code>pumpkin-plugins-build</code> command, which builds components and generates types. The old package and build command aren&#39;t included as compatibility shims. For a large existing plugin, the migration guide shows how to use a temporary pnpm dependency alias to avoid renaming every import at once.</p><h2 id="versioning" tabindex="-1">Versioning <a class="header-anchor" href="#versioning" aria-label="Permalink to “Versioning”">​</a></h2><p>While this package is below <code>1.0.0</code>, fixes and features use patch releases; breaking changes use the next minor release. For example, a breaking change from <code>0.1.0</code> becomes <code>0.2.0</code>. Once the package reaches <code>1.0.0</code>, it follows normal SemVer: fixes use patch versions, features use minor versions, and breaking changes require a major version.</p><p>Mark breaking commits with a Conventional Commit <code>!</code> marker, such as <code>feat!:</code> or a <code>BREAKING CHANGE</code> footer. Include release notes and migration steps so plugin authors can understand what changed and how to update.</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};